<template><view class="page"><view class="card"><text class="heading">业务数据导出</text><text class="muted">{{farmName}} · 按筛选条件逐页取全，最多5万条。</text><picker :range="options" range-key="label" @change="choose(Number($event.detail.value))"><view class="picker">{{config.label}} ⌄</view></picker><business-fields :fields="config.filters || []" v-model="filters" :farm-id="farmId"/><button class="primary" :disabled="busy" :loading="busy" @click="exportData">{{busy?'正在读取完整数据':'导出筛选结果 CSV'}}</button><text class="muted">下载内容包含当前筛选全部记录。导出过程中总数变化、重复分页或业务范围切换会中止。</text></view><view v-if="error" class="error">{{error}}</view><view v-if="done" class="card">已准备 {{done}} 条记录。</view></view></template>
<script setup lang="ts">
import {ref,computed} from 'vue'
import {onLoad,onShow,onHide} from '@dcloudio/uni-app'
import {date,text,select,choice,plot,type Row,type Resource} from '@/api/native-business'
import {allRows,csv,saveText,contextGuard} from '@/utils/business-files'
import {ensureWorkspaceSession,isProductionOps} from '@/utils/workspace'
import {resolveCurrentFarm} from '@/utils/auth-helper'
import BusinessFields from '@/components/business-fields/business-fields.vue'
const options:Resource[]=[{key:'tasks',label:'农事任务',url:'/tasks',id:'taskId',title:'taskName',subtitle:['plotName','taskType','status','planStartDate','planEndDate','assigneeName'],filters:[text('taskName','任务名称'),plot(),select('status','状态',choice({pending:'待分配',assigned:'已分配',in_progress:'执行中',completed:'已完成',cancelled:'已取消'}))]},{key:'harvests',label:'采收记录',url:'/harvests',id:'batchId',title:'batchNo',subtitle:['plotName','harvestDate','quantity','unit','grade','status'],filters:[text('batchNo','批次号'),plot(),date('startDate','开始日期'),date('endDate','结束日期')]},{key:'plots',label:'地块台账',url:'/plots',id:'plotId',title:'plotName',subtitle:['farmName','area','currentCrop','soilType','plantingType'],filters:[text('plotName','地块名称')]}]
const kind=ref('tasks'),filters=ref<Row>({}),farmId=ref(''),farmName=ref(''),error=ref(''),busy=ref(false),done=ref(0);let active=true
const config=computed(()=>options.find(o=>o.key===kind.value)||options[0]);function choose(i:number){if(busy.value)return;kind.value=options[i].key;filters.value={};done.value=0}
onLoad(o=>{kind.value=String(o?.kind||'tasks')});onShow(async()=>{active=true;try{if(!await ensureWorkspaceSession())return;if(isProductionOps())throw new Error('请切换到用户端');const farm=await resolveCurrentFarm();if(farm){farmId.value=String(farm.farmId);farmName.value=farm.farmName||''}}catch(e:any){error.value=e.message}});onHide(()=>{active=false;done.value=0})
async function exportData(){if(busy.value)return;busy.value=true;error.value='';done.value=0;try{if(!farmId.value)throw new Error('请先选择农场');if(filters.value.startDate>filters.value.endDate)throw new Error('日期范围无效');const scope=contextGuard(),guard=()=>{scope();if(!active)throw new Error('已离开导出页面')};const result=await allRows(config.value,{...filters.value,farmId:farmId.value},guard);guard();const labels:Row={taskId:'任务编号',taskName:'任务名称',plotName:'地块',taskType:'任务类型',status:'状态',planStartDate:'计划开始',planEndDate:'计划结束',assigneeName:'执行人',batchId:'采收编号',batchNo:'批次号',harvestDate:'采收日期',quantity:'数量',unit:'单位',grade:'等级',plotId:'地块编号',farmName:'农场',area:'面积亩',currentCrop:'当前作物',soilType:'土壤',plantingType:'种植类型'};const keys=[config.value.id!,config.value.title,...config.value.subtitle!];await saveText(config.value.label+'-筛选全部.csv',csv(result,keys.map(key=>({key,label:labels[key]||key}))));done.value=result.length}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<style scoped>.page{padding:24rpx;background:#f4f6f2;min-height:100vh;box-sizing:border-box}.card{padding:28rpx;border-radius:18rpx;background:white;margin-bottom:24rpx;font-size:28rpx}.heading{font-size:34rpx;font-weight:600;display:block}.muted{font-size:25rpx;color:#666666;display:block;line-height:1.7;margin:20rpx 0}.picker{padding:24rpx;background:#f0f4ec;border-radius:12rpx}.primary{background:#126d43;color:white;font-size:28rpx;margin-top:24rpx}.error{background:#fff0e8;color:#a43d28;padding:24rpx;font-size:26rpx}</style>
